<?php
namespace App\Http\Controllers\API;
use App\Http\Controllers\Controller;use App\Models\User;use App\Services\Username;use Illuminate\Database\QueryException;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\Validator;
class AuthController extends Controller {
 public function login(Request $request){$validator=Validator::make($request->all(),['email'=>'required|email','password'=>'required|min:6']);if($validator->fails())return response()->json(['status'=>false,'errors'=>$validator->errors()],422);$user=User::where('email',$request->email)->first();if(!$user||!Hash::check($request->password,$user->password))return response()->json(['errors'=>['password'=>['Invalid email or password']]],422);return response()->json(['token'=>$user->createToken('token')->plainTextToken,'user'=>$user]);}
 public function usernameAvailability(Request $request){$username=Username::normalize($request->query('username'));if(!Username::isFormatValid($username))return response()->json(['available'=>false,'valid'=>false,'message'=>'Use lowercase letters, numbers, _ or -. For example: studio-nova.']);if(Username::isReserved($username))return response()->json(['available'=>false,'valid'=>true,'message'=>'This username is reserved. Please choose another one.','suggestions'=>$this->suggestUsernames($username)]);$taken=User::where('username',$username)->exists();return response()->json(['available'=>!$taken,'valid'=>true,'message'=>$taken?'This username is already taken.':'Username is available.','suggestions'=>$taken?$this->suggestUsernames($username):[]]);}
 private function suggestUsernames(string $username):array{$base=substr($username,0,28);$candidates=collect(range(1,40))->map(fn($number)=>$base.$number)->reject(fn($candidate)=>Username::isReserved($candidate))->values();$taken=User::whereIn('username',$candidates)->pluck('username')->all();return $candidates->reject(fn($candidate)=>in_array($candidate,$taken,true))->take(4)->values()->all();}
 public function register(Request $request){$request->merge(['username'=>Username::normalize($request->input('username'))]);$validator=Validator::make($request->all(),['first_name'=>'required|string|max:255','last_name'=>'required|string|max:255','username'=>Username::rules(),'email'=>'required|email|unique:users,email','password'=>'required|string|min:8|same:confirm_password','confirm_password'=>'required']);if($validator->fails())return response()->json(['status'=>false,'errors'=>$validator->errors()],422);try{$user=User::create(['username'=>$request->username,'first_name'=>$request->first_name,'last_name'=>$request->last_name,'name'=>$request->first_name.' '.$request->last_name,'email'=>$request->email,'password'=>Hash::make($request->password),'role'=>in_array($request->role,['author','customer'],true)?$request->role:'customer']);}catch(QueryException $exception){$errors=[];if(User::where('username',$request->username)->exists())$errors['username']=['This username is already taken.'];if(User::where('email',$request->email)->exists())$errors['email']=['This email address is already registered.'];if($errors)return response()->json(['status'=>false,'errors'=>$errors],422);throw $exception;}return response()->json(['status'=>true,'message'=>'User registered successfully','user'=>$user],201);}
}